let profiles={};
let integrationStatus=null;
let serverResult=null, serverKey=null, savedInquiries=[], renderVersion=0, saving=false;
let comparisonTimer=null,comparisonRequestVersion=0,comparisonUpdating=false,comparisonError=null,chatNavigateAfterUpdate=false,comparisonController=null;
const providerCache={};
