const apiBase="/api/v1/guardian";
const disclaimer=document.querySelector?.('.app-disclaimer');if(disclaimer)disclaimer.textContent='Hackathon sandbox · All customer, vehicle, contract, service, coverage and financing data is synthetic. Provider results may be cached SerpApi evidence or clearly labeled synthetic fallback; prices, offers, service scope and authorization are unverified. The separate $50 scenario is simulated and never inferred from provider results. No real booking, payment or claim occurs. Assistant replies come through the backend and may use a validated Gemini response or deterministic fallback.';
function scenario(){return {profile:state.profile,miles:state.miles,repair:state.repair,reserve:state.reserve,discount:state.discount,fuel_price_per_gallon:state.fuelPrice,monthly_free_cash_flow:state.freeCashFlow===''?null:Number(state.freeCashFlow),upgrade_id:state.upgradeId,upgrade_mode:state.upgradeMode};}
async function api(path,body,options={}){const response=await fetch(apiBase+path,{headers:{"Content-Type":"application/json"},...(body?{method:"POST",body:JSON.stringify(body)}:{}),...(options.signal?{signal:options.signal}:{})});if(!response.ok)throw new Error(`Request failed (${response.status}). Please retry.`);return response.json();}
const stateDefaults={miles:12000,repair:1800,reserve:2000,discount:false,fuelPrice:3.5,fuelEvidence:null,filter:'all',sort:'distance',freeCashFlow:'',upgradeId:'corolla_hybrid',upgradeMode:'purchase'};
let selectedProfile='alex',profileStates={};
try{const saved=JSON.parse(localStorage.getItem('guardian-state-v2')||'null');if(saved?.selectedProfile)selectedProfile=saved.selectedProfile;if(saved?.profiles)profileStates=saved.profiles;else{const legacy=JSON.parse(localStorage.getItem('guardian-state')||'null');if(legacy?.profile){selectedProfile=legacy.profile;profileStates[legacy.profile]=legacy;}}}catch{}
let state={...stateDefaults,...profileStates[selectedProfile],profile:selectedProfile};
const allowedTabs=['overview','maintenance','local','compare','plan'];let currentTab=allowedTabs.includes(location.hash.slice(1))?location.hash.slice(1):'overview';
const plannedServices=[{id:'brakes',name:'Brake pads & rotor service',short:'Brake pads & rotors',detail:'A written demo estimate for front brake pads and rotors. Have a qualified technician verify the scope and whether the work is needed.',timing:'Confirmed estimate · Review with provider',status:'due',cost:1800,ico:'brake',badge:'Estimate ready',source:'Synthetic planning allowance'},{id:'oil',name:'Oil & filter service',short:'Oil & filter service',detail:'A routine maintenance allowance in the demo plan. Actual interval and price depend on your vehicle and service history.',timing:'Planned allowance · In the next 3 months',status:'due',cost:90,ico:'oil',badge:'Planned',source:'Synthetic planning allowance'},{id:'tires',name:'Tire rotation & inspection',short:'Tire rotation & inspection',detail:'A routine allowance for tire rotation and inspection. This does not predict tire condition or establish safety.',timing:'Planned allowance · In the next 6 months',status:'due',cost:60,ico:'tire',badge:'Planned',source:'Synthetic planning allowance'},{id:'inspection',name:'Remaining routine maintenance',short:'Other routine maintenance',detail:'An editable planning allowance for other routine service over 12 months. It is not a diagnosis or a model-specific service schedule.',timing:'Annual allowance · Scope to verify',status:'due',cost:450,ico:'tool',badge:'Allowance',source:'Synthetic planning allowance'}];
let services=[];let maintenanceUpdates={};try{maintenanceUpdates=JSON.parse(localStorage.getItem('guardian-maintenance-updates-v1')||'{}')}catch{}
const offers=[{id:'north',name:'North Loop Service Center',distance:3.2,rating:'4.7',count:218,price:1750,offer:'$50 off a brake service',type:'brakes',desc:'Illustrative local provider. Verify scope, taxes, eligibility and final price directly.',terms:'Demo promotion: $50 off the $1,800 brake estimate. Excludes taxes already included in this fixture. Cannot combine with the simulated coverage benefit. This is not a real business offer.'},{id:'cedar',name:'Cedar Park Auto Care',distance:8.6,rating:'4.8',count:164,price:85,offer:'Oil & filter service from $85',type:'oil',desc:'Illustrative local provider. Oil type, vehicle eligibility and additional fees need verification.',terms:'Demo price lead for an oil and filter service. Does not reduce the brake estimate and is not automatically applied to the comparison. Not a real quote.'},{id:'south',name:'South Austin Tire & Service',distance:11.4,rating:'4.6',count:306,price:45,offer:'Tire rotation from $45',type:'tires',desc:'Illustrative local provider. Final service scope and vehicle compatibility require verification.',terms:'Demo price lead for a tire rotation. Does not establish tire condition or replace a professional inspection. Not applied to the brake estimate. Not a real quote.'}];
function persist(){try{profileStates[state.profile]={miles:state.miles,repair:state.repair,reserve:state.reserve,discount:state.discount,fuelPrice:state.fuelPrice,fuelEvidence:state.fuelEvidence,filter:state.filter,sort:state.sort,upgradeId:state.upgradeId,upgradeMode:state.upgradeMode,...(state.freeCashFlow!==''?{freeCashFlow:state.freeCashFlow}:{})};localStorage.setItem('guardian-state-v2',JSON.stringify({selectedProfile:state.profile,profiles:profileStates}));}catch{toast('Browser storage is unavailable. Changes remain in this session.');}}
function profile(){return profiles?.[state.profile]||null;}
function vehicle(){return profile()?.vehicle||{};}
function contract(){return profile()?.contract||{};}
function vehicleName(){const v=vehicle();return [v.year,v.make,v.model,v.trim].filter(Boolean).join(' ')||'Synthetic Toyota';}
function sourceLabel(){return profile()?.source?.type==='snowflake'?'Synthetic Snowflake profile':'Local synthetic fallback';}
function serviceItems(){const updates=maintenanceUpdates[state.profile]||{};const planned=plannedServices.map(item=>{const u=updates[item.id];if(!u)return item;const detail=[u.provider&&`Provider: ${u.provider}`,u.date&&`Reported date: ${u.date}`,u.mileage&&`Mileage: ${Number(u.mileage).toLocaleString()} mi`,u.amount&&`Actual amount: ${money(u.amount)}`,u.notes].filter(Boolean).join(' · ');return {...item,status:u.status==='completed'?'completed':'due',badge:u.status==='completed'?'Self-reported complete':'Deferred by demo user',timing:u.status==='completed'?`Self-reported complete · ${u.date||'date not entered'}`:`Deferred · revisit ${u.date||'later'}`,detail:`${item.detail} ${detail}`,source:'Self-reported simulated data · browser-only'};});const history=(profile()?.service_history||[]).map((item,index)=>({id:item.service_id||`history-${index}`,name:item.service_type||'Recorded service',short:item.service_type||'Recorded service',detail:item.notes||'Synthetic service-history record returned by the backend.',timing:`Completed · ${item.service_date||'date unavailable'} · ${Number(item.mileage||0).toLocaleString()} mi`,status:'completed',cost:Number(item.cost||0),ico:'check',badge:'Completed',source:sourceLabel()}));services=[...planned,...history];return services;}
const vehicleAssets={camry:'assets/camry.png',corolla:'assets/corolla.png'};
function vehicleAsset(model){const key=String(model||'').toLowerCase();return Object.entries(vehicleAssets).find(([name])=>key.includes(name))?.[1]||'assets/vehicle.svg';}
function imageFallback(){return `onerror="this.onerror=null;this.src='assets/vehicle.svg'"`;}
function loadingView(label='Loading your synthetic account…'){return `<div class="guardian-skeleton" role="status" aria-live="polite"><div class="skeleton-line wide"></div><div class="skeleton-grid"><div class="skeleton-card"></div><div class="skeleton-card small"></div></div><div class="skeleton-line"></div><p>${escapeHTML(label)}</p></div>`;}
function loadProfileState(profileId){const saved=profileStates[profileId]||{};state={...stateDefaults,...saved,profile:profileId};const p=profiles[profileId];if(saved.reserve==null&&p?.reserve!=null)state.reserve=Number(p.reserve);if(saved.repair==null&&p?.service_needs?.[0]?.estimated_cost!=null)state.repair=Number(p.service_needs[0].estimated_cost);}
function syncAccountSwitcher(){const select=document.getElementById('account-profile-select');if(!select)return;select.innerHTML=Object.entries(profiles).map(([id,p])=>`<option value="${escapeHTML(id)}" ${id===state.profile?'selected':''}>${escapeHTML(p.name||p.label||id)}</option>`).join('');select.disabled=!Object.keys(profiles).length;}
function ensureAccountSwitcher(){const menu=document.querySelector?.('.customer-menu');if(!menu)return;if(!document.getElementById('account-profile-select')){const label=document.createElement('label');label.className='account-switcher';label.innerHTML='<span class="sr-only">Switch synthetic account</span><select id="account-profile-select" aria-label="Switch synthetic account" disabled><option>Loading…</option></select>';menu.appendChild(label);}if(!document.getElementById('reset-demo')){const button=document.createElement('button');button.type='button';button.id='reset-demo';button.className='reset-demo-button';button.setAttribute('aria-label','Reset this demo');button.textContent='Reset this demo';menu.appendChild(button);}}
function applyViewAssets(){const root=document.getElementById('guardian-view');if(!root)return;const current=root.querySelector?.('.vehicle-img,.compare-card img');if(current){current.src=vehicleAsset(vehicle().model);current.decoding='async';current.onerror=()=>{current.onerror=null;current.src='assets/vehicle.svg';};}const comparisonImages=root.querySelectorAll?.('.compare-card img')||[];if(comparisonImages[1]){comparisonImages[1].src='assets/corolla.png';comparisonImages[1].decoding='async';comparisonImages[1].onerror=()=>{comparisonImages[1].onerror=null;comparisonImages[1].src='assets/vehicle.svg';};}const providerImages=['assets/group1-service.jpg','assets/autonation-service.jpg','assets/autonation-dealer.jpg','assets/group1-dealer.jpg','assets/group1-service.jpg'];for(const [index,slot] of [...(root.querySelectorAll?.('.provider-art')||[])].entries()){if(slot.querySelector('img'))continue;const image=document.createElement('img');image.src=providerImages[index%providerImages.length];image.alt='';image.loading='lazy';image.decoding='async';image.setAttribute('aria-hidden','true');image.onerror=()=>{image.onerror=null;image.src='assets/service-center.jpg';};slot.prepend(image);}}
function providerResult(){return providerCache[state.profile]||null;}
function safeProviderLink(value){try{const url=new URL(value);return ['http:','https:'].includes(url.protocol)?url.href:null;}catch{return null;}}
function providerSource(result){if(!result)return 'Unavailable';if(result.source==='serpapi')return result.cached?'Cached SerpApi evidence':'Fresh SerpApi evidence';return 'Synthetic provider fallback';}
function retrievedLabel(value){if(!value)return 'Unavailable';const date=new Date(value);return Number.isNaN(date.valueOf())?'Unavailable':date.toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'});}
async function loadProviders(refresh=false,profileId=state.profile){if(!refresh&&providerCache[profileId])return providerCache[profileId];if(!refresh&&providerLoads[profileId])return providerLoads[profileId];providerLoading=true;providerError=null;if(profileId===state.profile)renderView();const request=(async()=>{try{const result=await api(`/providers?profile=${encodeURIComponent(profileId)}&refresh=${refresh?'true':'false'}`);providerCache[profileId]=result;return result;}catch(error){if(profileId===state.profile)providerError=error.message;return null;}finally{if(providerLoads[profileId]===request)delete providerLoads[profileId];providerLoading=Object.keys(providerLoads).length>0;if(profileId===state.profile)renderView();}})();providerLoads[profileId]=request;return request;}
function calc(){if(!serverResult||serverKey!==JSON.stringify(scenario()))throw new Error('Comparison is still updating.');return serverResult.calculation;}
function marketEvidence(){return marketCache[state.profile]||null;}
function marketView(){const result=marketEvidence();if(marketLoading)return `<section class="card coverage-panel"><div class="card-heading"><h2>Current fuel, vehicle & finance references</h2></div><p class="muted">Loading public sources…</p></section>`;if(!result)return `<section class="card coverage-panel"><div class="card-heading"><h2>Current fuel, vehicle & finance references</h2><button class="btn secondary small" id="refresh-market">Refresh public research</button></div><p class="muted">Search current Austin fuel research and public Toyota pricing, lease, and finance material only when you choose to refresh.</p></section>`;const categories=(result.categories||[]).map(category=>`<article class="saved-plan"><strong>${escapeHTML(category.label)}</strong><p>${escapeHTML(category.query||'')}</p>${(category.evidence||[]).map(item=>`<p><a href="${escapeHTML(safeProviderLink(item.url)||'#')}" target="_blank" rel="noopener noreferrer">${escapeHTML(item.title)}</a>${item.fact?` · ${escapeHTML(item.fact)}`:''}</p>`).join('')||`<p>${escapeHTML(category.warning||'No usable evidence returned.')}</p>`}</article>`).join('');const fuel=result.fuel_reference;const fuelAction=fuel?`<div class="evidence-banner"><strong>Fuel reference: ${money(fuel.price_per_gallon)}/gal</strong> · ${escapeHTML(fuel.attribution||'Public source')} · Needs your confirmation.<br><button class="btn secondary small" data-adopt-fuel="${escapeHTML(fuel.evidence_id)}">Use in my comparison</button></div>`:'';return `<section class="card coverage-panel"><div class="card-heading"><h2>Current fuel, vehicle & finance references</h2><button class="btn secondary small" id="refresh-market" ${marketLoading?'disabled':''}>Refresh public research</button></div><div class="evidence-banner">${icon('info')} ${escapeHTML(result.notice||'Public sources need verification. This does not change your comparison.')}</div>${categories||`<p class="muted">${escapeHTML(result.notice||marketError||'No public evidence is available.')}</p>`}${fuelAction}<p class="muted" style="font-size:10px;margin-top:12px">${result.cached?'Cached evidence':'Fresh evidence'}${result.retrieved_at?` · Retrieved ${retrievedLabel(result.retrieved_at)}`:''} · Needs verification</p></section>`;}
async function loadMarket(refresh=false){if(!refresh&&marketCache[state.profile])return marketCache[state.profile];marketLoading=true;marketError=null;renderView();try{const result=await api(`/market-evidence?profile=${encodeURIComponent(state.profile)}&refresh=${refresh?'true':'false'}`);marketCache[state.profile]=result;return result;}catch(error){marketError=error.message;return null;}finally{marketLoading=false;renderView();}}
function setComparisonStatus(message,error=false){const banner=document.getElementById('comparison-result');if(!banner)return;banner.setAttribute('aria-busy',String(!error&&comparisonUpdating));banner.className=`result-banner ${error?'warning':''}`;banner.innerHTML=`<span class="check-circle">${error?'!':'…'}</span><div><h3>${escapeHTML(message)}</h3>${error?'<button class="text-link" id="retry-comparison">Retry comparison</button>':'<p>Your current comparison remains visible while the new scenario is calculated.</p>'}</div>`;}
async function requestComparison(inputs){comparisonController?.abort();const controller=new AbortController();comparisonController=controller;try{return await api('/compare',inputs,{signal:controller.signal});}finally{if(comparisonController===controller)comparisonController=null;}}
async function updateComparison(){const requestVersion=++comparisonRequestVersion,inputs=scenario(),key=JSON.stringify(inputs);comparisonController?.abort();comparisonUpdating=true;comparisonError=null;setComparisonStatus('Updating comparison…');try{const result=await requestComparison(inputs);if(requestVersion!==comparisonRequestVersion)return;serverResult=result;serverKey=key;comparisonUpdating=false;comparisonError=null;if(chatNavigateAfterUpdate){chatNavigateAfterUpdate=false;currentTab='compare';if(location.hash!=='#compare')location.hash='compare';else renderView();}else if(currentTab==='compare')renderView();}catch(error){if(requestVersion!==comparisonRequestVersion||error.name==='AbortError')return;comparisonUpdating=false;comparisonError=error.message;chatNavigateAfterUpdate=false;setComparisonStatus(`Could not update comparison: ${error.message}`,true);}}
function scheduleComparisonUpdate(){comparisonRequestVersion++;comparisonController?.abort();comparisonController=null;comparisonUpdating=true;comparisonError=null;setComparisonStatus('Updating comparison…');clearTimeout(comparisonTimer);comparisonTimer=setTimeout(updateComparison,320);}
function getPlans(){return savedInquiries;}
function profileSelect(){return `<label class="profile-picker">${icon('user')} Switch synthetic profile<select id="profile-select" aria-label="Select synthetic customer profile">${Object.entries(profiles).map(([id,p])=>`<option value="${id}" ${state.profile===id?'selected':''}>${p.label}</option>`).join('')}</select></label>`;}
function recommendation(){return serverResult.recommendation;}
function overview(){const c=calc(),p=profile(),v=vehicle(),ct=contract(),r=recommendation(),items=serviceItems();const paid=Number(ct.payoff_amount||0)===0;return `<div class="evidence-banner">${icon('info')} ${sourceLabel()} · Customer, vehicle, contract and recorded service data came from the backend. Planning allowances remain illustrative.</div><div class="overview-top"><section class="card vehicle-card" aria-label="Your Toyota"><div class="eyebrow">YOUR TOYOTA</div><h2>${escapeHTML(vehicleName())}</h2><p class="vehicle-sub">Synthetic account vehicle · ${escapeHTML(p.profile_id)}</p><span class="badge ${paid?'green':''}">${icon(paid?'check':'info')} ${paid?'Paid off':money(ct.payoff_amount||0)+' payoff'}</span><img class="vehicle-img" src="assets/vehicle.svg" alt="Illustration of the synthetic account vehicle"><dl class="vehicle-stats"><div><dt>Current mileage</dt><dd>${Number(v.mileage||0).toLocaleString()} mi</dd></div><div><dt>Monthly driving</dt><dd>${Math.round(state.miles/12).toLocaleString()} mi</dd></div><div><dt>Monthly payment</dt><dd>${money(ct.monthly_payment||0)}</dd></div></dl>${profileSelect()}</section><section class="card health-card"><div class="card-heading"><h2>Your service snapshot</h2>${icon('shield')}</div><div class="health-score"><div class="score-ring"><div>${Math.min(5,(p.service_history||[]).length+3)}<span style="font-size:11px;color:#959c9f;margin-top:5px">/5</span></div></div><div><h3>One decision to make.</h3><p>Review your brake estimate.<br>Keep routine care on track.</p></div></div><div class="health-item"><span><i class="small-dot green-text"></i> Recorded services</span><strong>${(p.service_history||[]).length}</strong></div><div class="health-item"><span><i class="small-dot amber-text"></i> Repair estimate</span><strong class="amber-text">Needs review</strong></div><p style="font-size:8px;margin-top:10px">Demo checklist completion, not a mechanical health score.</p></section></div><div class="summary-grid"><section class="card summary-card"><div class="summary-top"><span>12-month service outlook</span>${icon('calendar')}</div><div class="summary-number">${money(c.oop+600)}</div><div class="summary-foot">Repair + routine allowances</div></section><section class="card summary-card"><div class="summary-top"><span>Potential repair coverage</span>${icon('shield')}</div><div class="summary-number">${money(c.coverage)}</div><div class="summary-foot ${c.coverage?'good':''}">${c.coverage?'Simulated benefit applied':'No coverage in this demo profile'}</div></section><section class="card summary-card"><div class="summary-top"><span>Keep vs. upgrade difference</span>${icon('trend')}</div><div class="summary-number">${money(Math.abs(c.difference))}</div><div class="summary-foot good">${c.difference>=0?'Less cash to keep':'Less cash to replace'} over 12 months</div></section></div><div class="main-columns"><section class="card service-card"><div class="card-heading"><h2>Coming up for your ${escapeHTML(v.model||'Toyota')}</h2><span class="badge">3 highlighted items</span></div>${items.filter(s=>s.status==='due').slice(0,3).map(s=>`<div class="service-row"><span class="service-icon">${icon(s.ico)}</span><div class="service-name"><h3>${s.short}</h3><p>${s.timing}</p></div><div class="service-end"><strong>${money(s.id==='brakes'?state.repair:s.cost)}</strong><span>${s.badge}</span></div></div>`).join('')}<div class="card-bottom"><small>Backend records + synthetic allowances</small><button class="text-link" data-tab="maintenance" style="font-size:10px">View all ${icon('arrow')}</button></div></section><section class="card insight-card"><div class="insight-top"><span class="spark">${icon('spark')}</span><h2>Your Guardian insight</h2><span class="badge">Demo</span></div><h3>${r.title}</h3><p>${c.keepOK?`Your ${escapeHTML(v.model||'Toyota')} has a ${money(state.repair)} repair estimate, and your monthly driving is ${Math.round(state.miles/12).toLocaleString()} miles. Let’s compare the trade-offs.`:r.text}</p><div class="insight-reason">${icon(c.keepOK?'check':'info')} ${c.keepOK?'Your reserve remains protected':'Your cash reserve needs attention'}</div><button class="btn full" data-tab="compare">See my comparison ${icon('arrow')}</button><div class="personal-note">Personalized with backend profile data and deterministic calculations. Explanations remain scripted for this first feature.</div></section></div><section class="offer-section"><div class="section-title"><h2>A little closer. A little less.</h2><button class="text-link" data-tab="local">View local offers ${icon('arrow')}</button></div><div class="offer-grid">${offers.map((o,i)=>`<article class="card offer-card"><div class="offer-label"><span class="offer-category">${['BRAKE SERVICE','ROUTINE MAINTENANCE','TIRES & WHEELS'][i]}</span>${icon('tag')}</div><div class="offer-discount">${['$50 off','From $85','From $45'][i]}</div><h3>${['Brake pads & rotor service','Oil & filter service','Tire rotation'][i]}</h3><p>${o.name} · Demo provider</p><span class="distance">${icon('pin')} ${o.distance} simulated miles away</span><button class="text-link" data-offer="${o.id}">See demo offer ${icon('arrow')}</button></article>`).join('')}</div><p class="offers-footnote">Illustrative offers and providers. No SerpApi search is used in this feature.</p></section>`;}
function maintenance(){let list=serviceItems().filter(x=>state.filter==='all'||x.status===state.filter);return `<div class="view-header"><div><h2>A clearer view of your service needs.</h2><p>Backend service history alongside clearly marked planning allowances.</p></div><div class="chip-row">${[['all','All items'],['due','Upcoming'],['completed','Completed']].map(([v,t])=>`<button class="chip ${state.filter===v?'active':''}" data-filter="${v}">${t}</button>`).join('')}</div></div><div class="maintenance-layout"><section class="card">${list.map(s=>`<article class="big-service-row"><span class="service-icon">${icon(s.ico)}</span><div><h3>${escapeHTML(s.name)}</h3><p>${escapeHTML(s.timing)}</p><small>${escapeHTML(s.source)}</small><button class="text-link" data-service="${s.id}" style="font-size:10px;display:block;margin-top:7px">View details ${icon('arrow')}</button></div><div style="text-align:right"><strong>${s.status==='completed'?'Completed':money(s.id==='brakes'?state.repair:s.cost)}</strong><div style="margin-top:9px"><span class="badge ${s.status==='completed'?'green':''}">${s.badge}</span></div></div></article>`).join('')}</section><aside><section class="card timeline"><div class="card-heading"><h2>Your 12-month outlook</h2>${icon('calendar')}</div><div class="timeline-item"><small>NOW · CONFIRMED ESTIMATE</small><h3>Review your brake service</h3><p>${money(state.repair)} before any applicable demo benefit. Verify the work and final quote.</p></div><div class="timeline-item"><small>NEXT 3 MONTHS · PLANNED</small><h3>Routine oil & filter service</h3><p>$90 synthetic planning allowance.</p></div><div class="timeline-item"><small>NEXT 6 MONTHS · PLANNED</small><h3>Tire rotation & inspection</h3><p>$60 synthetic planning allowance.</p></div><div class="timeline-item"><small>REMAINDER OF YEAR</small><h3>Other routine care</h3><p>$450 synthetic reserve for other service.</p></div></section><div class="evidence-banner" style="margin-top:15px">${icon('info')} Recorded items use ${sourceLabel().toLowerCase()}; upcoming items are planning fixtures, not a diagnosis or official schedule.</div><button class="btn full" data-tab="local">Explore service options ${icon('arrow')}</button></aside></div>`;}
function localView(){const c=calc(),result=providerResult(),items=result?.providers||[];const status=providerLoading?'Loading provider evidence…':providerError?`Provider results unavailable: ${escapeHTML(providerError)}`:`${providerSource(result)} · Retrieved ${retrievedLabel(result?.retrieved_at)}`;return `<div class="view-header"><div><h2>Find the right care, closer to home.</h2><p>Provider evidence for ${escapeHTML(result?.location||profile().region||'your demo area')}.</p></div><button class="btn secondary small" id="refresh-providers" ${providerLoading?'disabled':''}>${icon('search')} Refresh live results</button></div><div class="evidence-banner">${icon('info')} ${status}. Refreshing may consume one search API request. Prices, promotions, service scope and Toyota authorization are unverified; provider results never change the comparison discount.</div>${result?.warning?`<div class="evidence-banner">${icon('info')} ${escapeHTML(result.warning)}</div>`:''}${providerError?`<button class="btn secondary" id="retry-providers">Retry cached results</button>`:''}<div class="providers-list">${items.map((o,index)=>{const link=safeProviderLink(o.link);return `<article class="card provider"><div class="provider-art">${icon('building')}</div><span class="badge" style="align-self:start;margin-bottom:11px">${o.synthetic?'Synthetic fallback':'Search evidence'} · Needs verification</span><h3>${escapeHTML(o.name)}</h3><p>${o.rating==null?'Rating unavailable':`★ ${o.rating}`} ${o.review_count==null?'':`<span style="color:#aaa">(${Number(o.review_count).toLocaleString()} reviews)</span>`}</p><p>${escapeHTML(o.address||'Address unavailable')}</p><p>${o.distance?escapeHTML(o.distance):'Distance unavailable'} · Retrieved ${retrievedLabel(o.retrieved_at)}</p>${link?`<a class="btn secondary" href="${escapeHTML(link)}" target="_blank" rel="noopener noreferrer">Open provider website ${icon('external')}</a>`:`<button class="btn secondary" data-provider="${index}">View evidence details ${icon('arrow')}</button>`}</article>`;}).join('')}</div>${!providerLoading&&!items.length&&!providerError?`<div class="empty-state">${icon('building')}<p>No provider evidence is available. Try cached results again or deliberately refresh.</p></div>`:''}<section class="card coverage-panel"><div class="card-heading"><h2>Simulated brake-cost scenario</h2><button class="text-link" data-action="coverage" style="font-size:10px">Understand coverage ${icon('arrow')}</button></div><p class="muted" style="font-size:11px">This separate calculation fixture does not use any provider result, price, promotion or snippet.</p><div class="waterfall"><div class="waterfall-step"><small>Synthetic estimate</small><strong>${money(state.repair)}</strong><p>Editable scenario input</p></div><div class="waterfall-step"><small>Simulated $50 toggle</small><strong>−${money(c.discount)}</strong><p>${c.coverage?'Not stacked with coverage':state.discount?'Applied only to this scenario':'Optional simulation below'}</p></div><div class="waterfall-step"><small>Simulated coverage</small><strong>−${money(c.coverage)}</strong><p>${c.coverage?'Explicit fixture, not a live claim':'No coverage in this profile'}</p></div><div class="waterfall-step final"><small>Estimated customer cost</small><strong>${money(c.oop)}</strong><p>Not a provider quote</p></div></div><label class="check-field"><input type="checkbox" id="apply-discount" ${state.discount?'checked':''} ${c.coverage?'disabled':''}><span>Apply a synthetic $50 scenario adjustment. This is not sourced from SerpApi or any listed provider. ${c.coverage?'Switch to Alex to explore this fixture.':''}</span></label><button class="btn" data-tab="compare">Compare keeping vs. upgrading ${icon('arrow')}</button></section>`;}
function compare(){const c=calc(),r=recommendation(c);return `<div class="view-header"><div><h2>Your next move, with the numbers.</h2><p>A 12-month cash-flow comparison personalized to your demo profile.</p></div><button class="btn secondary small" data-action="assumptions">${icon('info')} Assumptions</button></div><div class="compare-top"><section class="card compare-card ${c.keepOK&&c.difference>=0?'recommended':''}"><span class="eyebrow" style="font-size:9px;color:#858d92">KEEP & SERVICE</span><span class="badge ${c.keepOK?'green':'red'}">${icon(c.keepOK?'check':'info')} ${c.keepOK?'Within upfront reserve':'Below cash reserve'}</span><h3>Your 2020 Camry LE</h3><img src="assets/vehicle.svg" alt="Your current silver sedan illustration"><div class="price-label">Estimated 12-month cash outflow</div><div class="compare-price">${money(c.keep)} <small>/ year</small></div><div class="sub-cost">${money(c.keep/12)} monthly equivalent · includes one-time repair</div><ul class="cost-list"><li><span>Existing loan payments</span><strong>$0</strong></li><li><span>Brake service after benefits</span><strong>${money(c.oop)}</strong></li><li><span>Other routine maintenance</span><strong>$600</strong></li><li><span>Fuel at 30 mpg</span><strong>${money(c.fuelKeep)}</strong></li><li><span>Cash remaining after repair</span><strong>${money(c.keepCash)}</strong></li></ul></section><section class="card compare-card"><span class="eyebrow" style="font-size:9px;color:#858d92">EXPLORE AN UPGRADE</span><span class="badge ${c.replaceOK?'':'red'}">${c.replaceOK?'Synthetic financing':'Below cash reserve'}</span><h3>2023 Corolla Hybrid LE</h3><img src="assets/vehicle.svg" style="filter:brightness(.75) sepia(.15)" alt="Illustration of a possible replacement sedan"><div class="price-label">Estimated 12-month cash outflow</div><div class="compare-price">${money(c.replace)} <small>/ year</small></div><div class="sub-cost">${money(c.replace/12)} monthly equivalent · includes cash due</div><ul class="cost-list"><li><span>Cash due at purchase</span><strong>$2,000</strong></li><li><span>Loan payments · $350 × 12</span><strong>$4,200</strong></li><li><span>Routine maintenance</span><strong>$300</strong></li><li><span>Fuel at 50 mpg</span><strong>${money(c.fuelReplace)}</strong></li><li><span>Cash remaining after purchase</span><strong>${money(c.replaceCash)}</strong></li></ul></section></div><section class="card controls-panel"><div class="control"><label for="miles-range">Annual driving <span class="control-value" id="miles-value">${state.miles.toLocaleString()} mi</span></label><input type="range" id="miles-range" min="6000" max="30000" step="1000" value="${state.miles}"><small>Changes fuel costs on both paths.</small></div><div class="control"><label for="repair-range">Brake estimate <span class="control-value" id="repair-value">${money(state.repair)}</span></label><input type="range" id="repair-range" min="500" max="4500" step="50" value="${state.repair}"><small>Confirmed demo estimate before benefits.</small></div><div class="control"><label for="reserve-range">Cash to protect <span class="control-value" id="reserve-value">${money(state.reserve)}</span></label><input type="range" id="reserve-range" min="500" max="6000" step="100" value="${state.reserve}"><small>Your minimum cash reserve after upfront costs.</small></div></section><div id="comparison-result" class="result-banner ${r.warning?'warning':''}"><span class="check-circle">${r.warning?'!':'✓'}</span><div><h3>${r.title}</h3><p>${r.text}</p></div></div><div style="display:flex;gap:12px;margin-top:20px;align-items:center;flex-wrap:wrap"><button class="btn" data-tab="plan">Make my next move ${icon('arrow')}</button><button class="btn secondary" data-tab="local">Review service options</button><span style="font-size:9px;color:#8e959b">Ending vehicle values are unknown. No total-cost winner is established.</span></div>`;}
function accountCompare(){const ct=contract(),c=calc(),flow=Number(state.freeCashFlow||0),monthlyKeep=Math.round(c.keep/12),monthlyReplace=Math.round(c.replace/12);const affordability=flow>0?`<div class="evidence-banner">${icon('info')} <strong>Monthly free cash flow (self-reported): ${money(flow)}</strong> · Keep uses about ${money(monthlyKeep)}/month and upgrade about ${money(monthlyReplace)}/month in this 12-month view. This is a planning signal, not an affordability decision.</div>`:`<div class="evidence-banner">${icon('info')} <strong>Ongoing affordability: unknown.</strong> We can check the upfront reserve, but do not know the customer’s monthly income or expenses. Add an optional self-reported monthly free-cash-flow amount to see a planning signal.</div>`;const input=`<section class="card card-pad" style="margin-top:16px"><label for="free-cash-flow"><strong>Optional monthly free cash flow</strong><br><small>After housing, debt, food and other commitments. Stored only in this browser for this synthetic profile; it is not sent to the backend.</small></label><div style="display:flex;gap:10px;align-items:center;margin-top:10px"><span>$</span><input id="free-cash-flow" type="number" min="0" step="50" value="${state.freeCashFlow===''?'':escapeHTML(state.freeCashFlow)}" placeholder="e.g. 900" style="max-width:180px"><button class="btn secondary small" id="save-free-cash-flow">Update planning signal</button></div><p class="muted" style="font-size:10px;margin-top:10px">Upfront reserve is checked separately: cash on hand minus one-time repair or cash due. The 12-month outflow includes fuel, routine service and payments; it is not assumed to be paid entirely from today’s cash.</p></section>`;return compare().replace('Your 2020 Camry LE',`Your ${escapeHTML(vehicleName())}`).replace('<li><span>Existing loan payments</span><strong>$0</strong></li>',`<li><span>Existing contract payments</span><strong>${money((ct.monthly_payment||0)*12)}</strong></li>`).replace('Your current silver sedan illustration','Your synthetic account vehicle illustration').replace('<div id="comparison-result"',affordability+input+'<div id="comparison-result"');}
function plan(){const c=calc(),r=recommendation(c),plans=getPlans();return `<div class="view-header"><div><h2>A clear next step for your Toyota.</h2><p>Turn your comparison into a practical, saved service plan.</p></div><button class="btn secondary small" id="export-plan">${icon('download')} Export plan</button></div><div class="plan-grid"><section class="card card-pad"><span class="badge ${r.warning?'red':'green'}">${r.warning?'Verify affordability':'Recommended next step'}</span><h2 style="font-size:21px;line-height:1.5;margin:15px 0 10px">${r.warning?'Get a second written estimate.':'Verify the repair. Keep your options clear.'}</h2><p class="muted" style="font-size:12px">${r.text}</p><div class="plan-step"><span class="step-number">1</span><div><h3>Confirm the brake-service scope</h3><p>Ask which components need work, whether taxes are included and how long the estimate is valid. Have safety questions answered by a qualified technician.</p></div></div><div class="plan-step"><span class="step-number">2</span><div><h3>${c.coverage?'Verify the coverage terms':'Ask about applicable local offers'}</h3><p>${c.coverage?`Your demo fixture provides ${money(c.coverage)}. In a real workflow, verify the covered item, deductible, limit and approval before counting on this benefit.`:'The illustrative $50 offer cannot be combined with the coverage fixture. Ask for a complete written quote before using any promotion.'}</p></div></div><div class="plan-step"><span class="step-number">3</span><div><h3>Revisit if the written quote changes</h3><p>Review this comparison if the estimate changes by $250 or more, your driving changes, or your cash needs shift. No background reminder is scheduled.</p></div></div><label class="check-field"><input id="plan-consent" type="checkbox"><span>I understand this is a simulated inquiry. Saving does not contact a provider, submit a claim or book an appointment.</span></label><button id="save-plan" class="btn full" disabled>${icon('save')} Save my demo service inquiry</button></section><aside><section class="card card-pad"><div class="card-heading"><h2>Your plan snapshot</h2>${icon('file')}</div><ul class="cost-list"><li><span>Demo customer</span><strong>${profile().name}</strong></li><li><span>Account vehicle</span><strong>${escapeHTML(vehicleName())}</strong></li><li><span>Profile source</span><strong>${sourceLabel()}</strong></li><li><span>Brake service cost</span><strong>${money(c.oop)}</strong></li><li><span>12-month keep cash outflow</span><strong>${money(c.keep)}</strong></li><li><span>Protected reserve</span><strong>${money(state.reserve)}</strong></li></ul><div class="integration-note">Saved in the backend’s local demo database, separately for each synthetic profile. No provider is contacted.</div></section><section class="card card-pad" style="margin-top:18px"><div class="card-heading"><h2>Saved demo inquiries</h2><span class="badge">${plans.length}</span></div>${plans.length?plans.slice(0,4).map(x=>`<div class="saved-plan"><strong>${escapeHTML(x.name)} · Service review</strong><p>${new Date(x.createdAt).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})} · ${money(x.cost)} customer cost</p><p>Simulated inquiry · No provider contacted</p></div>`).join(''):`<div class="empty-state">${icon('save')}<p>Your saved inquiries will appear here.</p></div>`}</section></aside></div>`;}
function renderView(){const root=document.getElementById('guardian-view'),p=profile();document.querySelectorAll('.tabnav button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===currentTab);b.setAttribute('aria-current',b.dataset.tab===currentTab?'page':'false');});if(!p||!serverResult){root.innerHTML=loadingView();return;}const funcs={overview,maintenance,local:()=>localView()+marketView(),compare:accountCompare,plan};root.innerHTML=`<div class="content-view view-enter">${funcs[currentTab]()}</div>`;const name=document.getElementById('customer-name'),avatar=document.getElementById('avatar');if(name)name.textContent=p.name||'Synthetic account';if(avatar)avatar.textContent=p.initials||'--';syncAccountSwitcher();applyViewAssets();hydrateIcons();}
async function render(showLoadingSkeleton=false){
  const version=++renderVersion, inputs=scenario(), key=JSON.stringify(inputs);
  const root=document.getElementById('guardian-view');
  try{
    if(!serverResult||serverKey!==key){
      root.innerHTML=showLoadingSkeleton?loadingView('Updating comparison…'):'<div class="card card-pad" role="status">Updating your comparison…</div>';
      const result=await requestComparison(inputs);
      if(version!==renderVersion)return;
      serverResult=result;serverKey=key;
    }
    if(currentTab==='plan'){
      savedInquiries=(await api('/history?profile='+encodeURIComponent(inputs.profile))).inquiries;
      if(version!==renderVersion)return;
    }
    if(currentTab==='local'&&!providerCache[inputs.profile]){
      await loadProviders(false,inputs.profile);
      if(version!==renderVersion)return;
    }
    renderView();
  }catch(error){if(error.name==='AbortError')return;if(version===renderVersion)root.innerHTML='<div class="card card-pad" role="alert"><h2>Unable to load your demo</h2><p>'+escapeHTML(error.message)+'</p><button class="btn" id="retry-api">Retry</button></div>';}
}
document.addEventListener('click',e=>{if(e.target.closest('#retry-api'))render();});
document.addEventListener('click',async e=>{if(e.target.closest('#refresh-market')){modal('Refresh public research',`<p>This performs five bounded SerpApi searches: Austin fuel, three Toyota vehicle/lease candidates, and regional Toyota financing. It may consume five search API requests and will not change your comparison.</p><button class="btn" id="confirm-market-refresh">Refresh research ${icon('search')}</button>`);}if(e.target.closest('#confirm-market-refresh')){closeModal();await loadMarket(true);toast('Public research refreshed. Verify every source.');}if(e.target.closest('#refresh-providers')){modal('Refresh provider evidence',`<p>This deliberately requests fresh provider results and may consume one search API request. Results are evidence only: prices, promotions, service scope and authorization remain unverified.</p><button class="btn" id="confirm-provider-refresh">Refresh now ${icon('search')}</button>`);}if(e.target.closest('#confirm-provider-refresh')){closeModal();await loadProviders(true);toast('Provider evidence refreshed. Verify all details independently.');}if(e.target.closest('#retry-providers'))await loadProviders(false);});
function navigate(tab){if(!allowedTabs.includes(tab))return;currentTab=tab;renderView();if(location.hash.slice(1)!==tab)history.replaceState(null,'','#'+tab);if(tab==='local'&&!providerCache[state.profile])loadProviders(false);if(tab==='plan'){loadPlanHistory();loadNextMoveSummary();}}
window.addEventListener('hashchange',()=>{navigate(allowedTabs.includes(location.hash.slice(1))?location.hash.slice(1):'overview');});
async function loadPlanHistory(){const profileId=state.profile;try{savedInquiries=(await api('/history?profile='+encodeURIComponent(profileId))).inquiries;if(profileId===state.profile&&currentTab==='plan')renderView();}catch(error){toast(`Saved plans unavailable: ${error.message}`);}}
function assumptions(){modal('Comparison assumptions',`<p>This is an illustrative 12-month cash-flow comparison. It does not establish total cost of ownership or a market recommendation.</p><dl><div><dt>Current vehicle loan</dt><dd>Paid off · $0</dd></div><div><dt>Gasoline price</dt><dd>$3.50 / gallon</dd></div><div><dt>Assumed fuel efficiency</dt><dd>30 mpg / 50 mpg</dd></div><div><dt>Replacement cash due</dt><dd>$2,000</dd></div><div><dt>Replacement financing</dt><dd>$350 / month · 60 months</dd></div><div><dt>Illustrative APR</dt><dd>8.0% · No approval implied</dd></div><div><dt>Insurance & registration</dt><dd>Assumed equal</dd></div><div><dt>Terminal vehicle values</dt><dd>Unknown</dd></div></dl><p>The replacement payment is a synthetic quote, not a rate you qualify for. An illustrative principal of about $17,261 at 8% over 60 months produces this payment; the existing vehicle’s simulated trade credit and upfront cash are assumed reflected in the quote. Actual transaction terms require verification.</p>`);}
function coverageModal(){const c=calc();modal('Protection that’s specific to you',`<span class="badge">Synthetic coverage illustration</span><p style="margin-top:14px">${c.coverage?`This demo profile has an explicit benefit fixture covering up to $1,000 of the confirmed brake repair, with no deductible. The applied benefit is ${money(c.coverage)}.`:'This demo profile has no applicable repair coverage. It does not represent your real protection plans.'}</p><ul><li>Coverage is not inferred from account tenure or vehicle age.</li><li>The $50 demo special cannot stack with the coverage fixture.</li><li>Real covered items, exclusions and claims require plan-specific verification.</li></ul><p>No live policy, warranty or claim check has been performed.</p>`);}
function offerModal(id){const o=offers.find(x=>x.id===id);if(!o)return;modal(o.offer,`<span class="badge">Illustrative offer · Not live search</span><p style="margin-top:15px"><strong>${o.name}</strong><br>Austin area · ${o.distance} simulated miles away</p><p style="margin-top:12px">${o.terms}</p><dl><div><dt>Evidence source</dt><dd>Synthetic demo fixture</dd></div><div><dt>Provider authorization</dt><dd>Unverified</dd></div><div><dt>Quote status</dt><dd>Needs verification</dd></div></dl>${o.id==='north'?`<button class="btn" id="apply-offer-modal" ${profile().coverage?'disabled':''}>${profile().coverage?'Cannot stack with current coverage':'Apply $50 demo offer'} ${icon('arrow')}</button>`:`<a class="btn secondary" href="https://www.google.com/maps/search/Toyota+service+Austin+TX" target="_blank" rel="noopener">Search real service providers ${icon('external')}</a>`}<p style="font-size:10px;margin-top:13px">External search opens Google Maps; it is not a SerpApi integration.</p>`);}
function exportPlan(){if(serverKey!==JSON.stringify(scenario()))return;const c=calc();const data={product:'Toyota TCO & Smart Service Guardian',mode:'synthetic-demo',customer:profile().name,vehicle:vehicleName(),profileSource:profile().source,createdAt:new Date().toISOString(),inputs:{annualMiles:state.miles,repairEstimate:state.repair,reserve:state.reserve,coverage:c.coverage,discount:c.discount},cashflow:{repairCustomerCost:c.oop,keep12Months:c.keep,replace12Months:c.replace},recommendation:recommendation(),notice:'No provider contacted. No real quote, claim or booking. Cash-flow comparison only.'};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='toyota-guardian-demo-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Demo plan exported as JSON.');}
document.addEventListener('click',async e=>{if(e.target.closest('#reset-demo'))await resetDemoScenario();const tab=e.target.closest('[data-tab]');if(tab){e.preventDefault();navigate(tab.dataset.tab);}const filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;persist();render();}const service=e.target.closest('[data-service]');if(service){const s=services.find(x=>x.id===service.dataset.service);modal(s.name,`<span class="badge">Synthetic service record</span><p style="margin-top:14px">${s.detail}</p><dl><div><dt>Status</dt><dd>${s.badge}</dd></div><div><dt>Planning amount</dt><dd>${money(s.id==='brakes'?state.repair:s.cost)}</dd></div><div><dt>Data source</dt><dd>Demo fixture</dd></div></dl><button class="btn" data-modal-go="local">Explore service options ${icon('arrow')}</button>`);}const offer=e.target.closest('[data-offer]');if(offer)offerModal(offer.dataset.offer);const act=e.target.closest('[data-action]');if(act?.dataset.action==='coverage')coverageModal();if(act?.dataset.action==='assumptions')assumptions();if(e.target.closest('[data-modal-go]')){closeModal();navigate('local');}if(e.target.closest('#apply-offer-modal')){state.discount=true;persist();closeModal();navigate('local');render();toast('Illustrative $50 offer applied. Verify terms before use.');}if(e.target.closest('#export-plan'))exportPlan();if(e.target.closest('#save-plan')){
  if(saving||!document.getElementById('plan-consent')?.checked)return;
  saving=true;e.target.closest('#save-plan').disabled=true;
  try{await api('/inquiries',{inputs:scenario(),consent:true,request_id:crypto.randomUUID()});await render();toast('Demo inquiry saved on the server. No provider contacted.');}
  catch(error){toast(error.message);const button=document.getElementById('save-plan');if(button)button.disabled=false;}
  finally{saving=false;}
}});

async function switchProfile(profileId){if(!profiles[profileId]||profileId===state.profile)return;persist();clearTimeout(comparisonTimer);comparisonRequestVersion++;comparisonController?.abort();comparisonController=null;comparisonUpdating=false;serverResult=null;serverKey=null;chatHistory=[];loadProfileState(profileId);persist();syncAccountSwitcher();document.getElementById('guardian-view').innerHTML=loadingView(`Loading ${profiles[profileId].name}'s synthetic account…`);await render();toast(`Loaded ${profiles[profileId].name.split(' ')[0]}’s synthetic profile.`);}
async function resetDemoScenario(){const profileId=state.profile;clearTimeout(comparisonTimer);comparisonRequestVersion++;comparisonController?.abort();comparisonController=null;comparisonUpdating=false;serverResult=null;serverKey=null;state={...stateDefaults,reserve:Number(profile()?.reserve??stateDefaults.reserve),repair:Number(profile()?.service_needs?.[0]?.estimated_cost??stateDefaults.repair),profile:profileId};persist();await render(true);toast('Reset this synthetic scenario.');}
document.addEventListener('change',e=>{if(['profile-select','account-profile-select'].includes(e.target.id))switchProfile(e.target.value);if(e.target.id==='offer-sort'){state.sort=e.target.value;persist();renderView();}if(e.target.id==='apply-discount'){state.discount=e.target.checked;persist();render();}if(e.target.id==='upgrade-select'){state.upgradeId=e.target.value;persist();render(true);}if(e.target.id==='upgrade-mode'){state.upgradeMode=e.target.value;persist();render(true);}if(e.target.id==='plan-consent')document.getElementById('save-plan').disabled=!e.target.checked;if(['miles-range','repair-range','reserve-range'].includes(e.target.id))persist();});
document.addEventListener('input',e=>{const map={'miles-range':'miles','repair-range':'repair','reserve-range':'reserve'};if(map[e.target.id]){
state[map[e.target.id]]=Number(e.target.value);
document.getElementById(e.target.id.replace('range','value')).textContent=e.target.id==='miles-range'?state.miles.toLocaleString()+' mi':money(Number(e.target.value));
persist();scheduleComparisonUpdate();
}});
document.addEventListener('click',e=>{if(e.target.closest('#retry-comparison'))updateComparison();if(e.target.closest('#save-free-cash-flow')){const input=document.getElementById('free-cash-flow');const value=input?.value.trim();state.freeCashFlow=value===''?'':Math.min(50000,Math.max(0,Number(value)||0));persist();render(true);toast('Updated the monthly affordability check.');}});
function serviceUpdateModal(id){const s=plannedServices.find(item=>item.id===id);if(!s)return;const existing=maintenanceUpdates[state.profile]?.[id]||{};modal(`Update ${s.short}`,`<p>Report a completion or deferral for this synthetic plan. This is <strong>self-reported simulated data</strong>, stored only in this browser; it does not change Snowflake or contact a provider.</p><form id="maintenance-update-form" data-service-id="${id}"><label>Status<select name="status"><option value="completed" ${existing.status==='completed'?'selected':''}>Completed</option><option value="deferred" ${existing.status==='deferred'?'selected':''}>Deferred</option></select></label><label>Date<input name="date" type="date" value="${existing.date||''}"></label><label>Mileage<input name="mileage" type="number" min="0" value="${existing.mileage||vehicle().mileage||''}"></label><label>Provider or repair shop<input name="provider" maxlength="100" value="${escapeHTML(existing.provider||'')}"></label><label>Actual amount paid<input name="amount" type="number" min="0" step="0.01" value="${existing.amount||''}"></label><label>Notes<textarea name="notes" maxlength="300">${escapeHTML(existing.notes||'')}</textarea></label><button class="btn" type="submit">Save self-reported update ${icon('save')}</button></form>`);}
document.addEventListener('click',e=>{const detail=e.target.closest('[data-service]');if(detail){const id=detail.dataset.service;setTimeout(()=>{if(plannedServices.some(x=>x.id===id)&&document.querySelector('.modal')){const b=document.createElement('button');b.className='btn secondary';b.style.marginTop='10px';b.dataset.serviceUpdate=id;b.textContent='Report completion or defer';document.querySelector('.modal').appendChild(b);}},0);}const update=e.target.closest('[data-service-update]');if(update){e.preventDefault();serviceUpdateModal(update.dataset.serviceUpdate);}});
document.addEventListener('submit',e=>{if(e.target.id!=='maintenance-update-form')return;e.preventDefault();const form=e.target,data=new FormData(form),id=form.dataset.serviceId;const record={status:data.get('status'),date:String(data.get('date')||''),mileage:Number(data.get('mileage')||0),provider:String(data.get('provider')||'').trim(),amount:Number(data.get('amount')||0),notes:String(data.get('notes')||'').trim()};maintenanceUpdates[state.profile]={...(maintenanceUpdates[state.profile]||{}),[id]:record};try{localStorage.setItem('guardian-maintenance-updates-v1',JSON.stringify(maintenanceUpdates));}catch{}if(id==='brakes'){state.repair=record.status==='completed'?0:(record.amount||state.repair);persist();}closeModal();id==='brakes'?render(true):renderView();toast(id==='brakes'?'Saved the update and recalculated the brake scenario.':'Saved self-reported simulated service update in this browser.');});
let assistantOpen=false,chatLoading=false,chatHistory=[],lastFailedMessage=null,pendingScenarioChange=null,nextMoveSummary=null,nextMoveLoading=false,nextMoveKey=null;
function userReportedContext(){const updates=maintenanceUpdates[state.profile]||{};return {monthly_free_cash_flow:state.freeCashFlow===''?null:Number(state.freeCashFlow),selected_upgrade:`${state.upgradeId}:${state.upgradeMode}`,maintenance_updates:Object.entries(updates).slice(0,8).map(([id,value])=>`${id}: ${value.status||'updated'}${value.date?` on ${value.date}`:''}${value.amount?` for ${money(value.amount)}`:''}`)};}
function openAssistant(){if(!profiles[state.profile])return;assistantOpen=!assistantOpen;const root=document.getElementById('assistant-root');if(!assistantOpen){root.innerHTML='';return;}root.innerHTML=`<aside class="assistant-panel" aria-label="Demo Guardian assistant"><div class="assistant-head"><span class="spark">${icon('spark')}</span><div><h3>Your Guardian</h3><p>Backend assistant · Synthetic account context</p></div><button class="icon-btn" id="close-assistant" aria-label="Close assistant">${icon('close')}</button></div><div class="chat-log" id="chat-log" aria-live="polite"><div class="message">Hi ${profile().name.split(' ')[0]}. I can explain the current backend comparison or propose a scenario change for your confirmation. Provider evidence remains unverified.</div></div><div class="chat-suggestions"><button data-chat="Why is keeping my Toyota the current recommendation?">Explain the recommendation</button><button data-chat="What does my coverage mean?">Explain coverage</button><button data-chat="Set annual mileage to 24000">Propose 24,000 mi/year</button></div><form class="chat-form" id="chat-form"><label for="chat-input" class="sr-only">Ask a demo question</label><input id="chat-input" placeholder="Ask about your next move…" autocomplete="off" maxlength="1000"><button id="chat-submit" aria-label="Send question">${icon('arrow')}</button></form></aside>`;document.getElementById('chat-input').focus();}
function appendMessage(text,type='assistant',meta=''){const log=document.getElementById('chat-log');if(!log)return;const msg=document.createElement('div');msg.className='message '+(type==='user'?'user':'');msg.textContent=text;if(meta){const note=document.createElement('small');note.textContent=meta;msg.appendChild(document.createElement('br'));msg.appendChild(note);}log.appendChild(msg);while(log.children.length>12)log.removeChild(log.children[0]);log.scrollTop=log.scrollHeight;}
function boundedChatHistory(){return chatHistory.slice(-6).map(x=>({role:x.role,content:x.content.slice(0,500)}));}
function setChatLoading(value){chatLoading=value;const input=document.getElementById('chat-input'),button=document.getElementById('chat-submit');if(input)input.disabled=value;if(button)button.disabled=value;document.querySelectorAll('[data-chat]').forEach(x=>x.disabled=value);}
function proposeScenarioChange(change){pendingScenarioChange=change;modal('Confirm your scenario change',`<p>${escapeHTML(change.label)}? This changes only the synthetic scenario and will recalculate after you confirm.</p><button class="btn" id="confirm-chat-change">Confirm & recalculate ${icon('arrow')}</button>`);}
async function askGuardian(q,{retry=false}={}){q=q.trim();if(!q||chatLoading)return;if(!serverResult||serverKey!==JSON.stringify(scenario())){appendMessage('Please wait for the current comparison to finish updating.');return;}const history=boundedChatHistory();if(!retry){appendMessage(q,'user');chatHistory.push({role:'user',content:q});}setChatLoading(true);appendMessage('Thinking with your synthetic account context…','assistant',`Gemini request · ${integrationStatus?.gemini?.model||'configured model'}`);try{const response=await api('/chat',{profile:state.profile,scenario:scenario(),view:currentTab,message:q,history,user_context:userReportedContext()});const log=document.getElementById('chat-log');if(log?.lastElementChild?.textContent.startsWith('Thinking with'))log.lastElementChild.remove();const source=response.fallback?'Deterministic fallback':`Gemini · ${integrationStatus?.gemini?.model||'validated response'}`;const citations=(response.cited_evidence_ids||[]).length?` · Evidence: ${response.cited_evidence_ids.join(', ')}`:'';const warning=response.warning?` · ${response.warning}`:'';appendMessage(response.message,'assistant',`${source}${citations}${warning}`);chatHistory.push({role:'assistant',content:String(response.message).slice(0,500)});chatHistory=chatHistory.slice(-6);lastFailedMessage=null;if(response.scenario_change)proposeScenarioChange(response.scenario_change);}catch(error){const log=document.getElementById('chat-log');if(log?.lastElementChild?.textContent.startsWith('Thinking with'))log.lastElementChild.remove();lastFailedMessage=q;appendMessage(`Could not reach the assistant: ${error.message}`,'assistant','Your scenario was not changed. Use Retry below.');const retryButton=document.createElement('button');retryButton.id='retry-chat';retryButton.className='text-link';retryButton.textContent='Retry';document.getElementById('chat-log')?.appendChild(retryButton);}finally{setChatLoading(false);}}
document.addEventListener('click',async e=>{if(e.target.closest('#assistant-toggle')||e.target.closest('#close-assistant'))openAssistant();const suggestion=e.target.closest('[data-chat]');if(suggestion)await askGuardian(suggestion.dataset.chat);if(e.target.closest('#retry-chat')&&lastFailedMessage)await askGuardian(lastFailedMessage,{retry:true});if(e.target.closest('#confirm-chat-change')&&pendingScenarioChange){const change=pendingScenarioChange;pendingScenarioChange=null;if(Object.hasOwn(state,change.field))state[change.field]=change.value;persist();closeModal();chatNavigateAfterUpdate=true;scheduleComparisonUpdate();appendMessage(`Applied after confirmation: ${change.label}`,'assistant','Synthetic scenario updated');}});document.addEventListener('submit',async e=>{if(e.target.id==='chat-form'){e.preventDefault();const input=document.getElementById('chat-input'),q=input.value.trim();if(q&&!chatLoading){input.value='';await askGuardian(q);}}});
async function boot(){
  ensureAccountSwitcher();wireAccountLinks();document.getElementById('guardian-view').innerHTML=loadingView('Loading synthetic profiles…');
  try{const [profileResponse,statusResponse]=await Promise.all([api('/profiles'),api('/integration-status').catch(()=>null)]);profiles=profileResponse.profiles||{};integrationStatus=statusResponse;const ids=Object.keys(profiles);if(!ids.length)throw new Error('No synthetic profiles are available.');if(!profiles[state.profile])loadProfileState(ids[0]);else loadProfileState(state.profile);persist();syncAccountSwitcher();await render();}
  catch(error){document.getElementById('guardian-view').innerHTML='<div class="card card-pad" role="alert">Unable to connect. Open this page through the backend at /site/guardian.html. <button class="btn" id="retry-boot">Retry</button></div>';}
}
function wireAccountLinks(){const side=document.querySelector('.sidebar');if(!side)return;const targets={Dashboard:'account.html#dashboard',Payments:'account.html#payments','Account details':'account.html#details','My protection':'account.html#protection'};side.querySelectorAll('.side-link').forEach(el=>{const label=el.textContent.trim();if(!targets[label])return;const a=document.createElement('a');a.className=el.className;a.href=targets[label];a.innerHTML=el.innerHTML;el.replaceWith(a);});}
document.addEventListener('click',e=>{if(e.target.closest('#retry-boot'))boot();});
// Boot after the enhancement functions below are installed so first paint and later renders
// use the same implementation. Previously boot raced the overrides and produced stale UI.

// Keep public research opt-in: only a user-confirmed AAA reference can change fuel inputs.
const guardianCompareLegacy=compare;
compare=function(){const c=calc(),market=marketEvidence();const fuelNote=state.fuelEvidence?`<div class="evidence-banner">${icon('fuel')} Using confirmed public fuel reference: <strong>${money(c.fuelPrice)}/gal</strong> · ${escapeHTML(state.fuelEvidence.title||'AAA public research')}. It changes fuel planning only, not coverage or financing.</div>`:`<div class="evidence-banner">${icon('info')} Fuel planning uses the synthetic default of $3.50/gal. ${market?.fuel_reference?`<button class="text-link" data-adopt-fuel="${escapeHTML(market.fuel_reference.evidence_id)}">Review cached public reference</button>`:'Refresh public research on Local service offers to review an attributable fuel reference.'}</div>`;return guardianCompareLegacy().replace('<div class="compare-top">',fuelNote+'<div class="compare-top">');};

document.addEventListener('click',async e=>{const button=e.target.closest('[data-adopt-fuel]');if(!button)return;e.preventDefault();try{const proposal=await api('/market-evidence/adopt-fuel',{profile:state.profile,evidence_id:button.dataset.adoptFuel});modal('Use public fuel reference?',`<p>${escapeHTML(proposal.notice||'Confirm this planning input before it is used.')}</p><dl><div><dt>Proposed fuel planning input</dt><dd>${money(proposal.fuel_price_per_gallon)}/gallon</dd></div><div><dt>Source</dt><dd>${escapeHTML(proposal.fuel_evidence?.attribution||'Public research')}</dd></div></dl><button class="btn" id="confirm-adopt-fuel" data-fuel-price="${escapeHTML(String(proposal.fuel_price_per_gallon))}" data-fuel-title="${escapeHTML(proposal.fuel_evidence?.title||'AAA public research')}" data-fuel-retrieved="${escapeHTML(proposal.fuel_evidence?.retrieved_at||'')}">Confirm & recalculate ${icon('arrow')}</button>`);}catch(error){toast(error.message);}});
document.addEventListener('click',e=>{const button=e.target.closest('#confirm-adopt-fuel');if(!button)return;state.fuelPrice=Number(button.dataset.fuelPrice);state.fuelEvidence={title:button.dataset.fuelTitle,retrieved_at:button.dataset.fuelRetrieved};persist();closeModal();scheduleComparisonUpdate();toast('Confirmed public fuel reference for this browser-only scenario.');});

// Cached Google Maps image URLs are displayed only when returned by the existing provider search.
const guardianLocalViewLegacy=localView;
const cachedProviderPhotos=['assets/group1-service.jpg','assets/autonation-service.jpg','assets/autonation-dealer.jpg','assets/group1-dealer.jpg','assets/group1-service.jpg'];
localView=function(){let index=0;return guardianLocalViewLegacy().replace(/<div class="provider-art">[\s\S]*?<\/div>/g,()=>{const provider=(providerResult()?.providers||[])[index];const image=safeProviderLink(provider?.image_url)||cachedProviderPhotos[index%cachedProviderPhotos.length];index++;return `<div class="provider-art"><img src="${escapeHTML(image)}" alt="Photo of ${escapeHTML(provider?.name||'Toyota service center')}" loading="lazy" referrerpolicy="no-referrer" onerror="this.onerror=null;this.src='assets/service-center.jpg'"></div>`;});};
const guardianApplyViewAssetsLegacy=applyViewAssets;
applyViewAssets=function(){guardianApplyViewAssetsLegacy();for(const slot of document.querySelectorAll('.provider-art')){const images=slot.querySelectorAll('img');if(images.length>1){const providerImage=images[images.length-1];for(const image of images)if(image!==providerImage)image.remove();}}};
// Market references are deliberately separate from calculation inputs until a user confirms one.
const guardianAssumptionsLegacy=assumptions;
assumptions=function(){const c=calc(),market=marketEvidence(),fuel=state.fuelEvidence?`Confirmed public reference · ${escapeHTML(state.fuelEvidence.title||'AAA public research')}`:'Synthetic default until a public reference is confirmed';const research=(market?.categories||[]).filter(x=>x.label!=='Fuel-price research').map(category=>`<div><dt>${escapeHTML(category.label)}</dt><dd>${(category.evidence||[]).length?'Cached public references available':'No cached reference'}</dd></div>`).join('');modal('Comparison inputs & live references',`<p>This is an illustrative 12-month cash-flow comparison. It does not establish total ownership cost, a vehicle offer, an approval, or a market recommendation.</p><dl><div><dt>Fuel planning input</dt><dd>${money(c.fuelPrice)}/gallon</dd></div><div><dt>Fuel source</dt><dd>${fuel}</dd></div><div><dt>Vehicle efficiency model</dt><dd>30 mpg / 50 mpg</dd></div><div><dt>Replacement cash due</dt><dd>$2,000 synthetic scenario input</dd></div><div><dt>Replacement financing</dt><dd>$350/month · synthetic scenario input</dd></div><div><dt>Interest rate / lease terms</dt><dd>Not used until verified public research is reviewed</dd></div>${research}<div><dt>Insurance & registration</dt><dd>Not modeled</dd></div><div><dt>Terminal vehicle values</dt><dd>Unknown</dd></div></dl><p>Use Local service offers → Refresh public research to retrieve at most three current public references: fuel, Toyota vehicle/lease information, and Toyota financing information. They are displayed for review and never silently change this calculation.</p>`);};
const guardianCompareWithFuel=compare;
compare=function(){const market=marketEvidence();const cards=(market?.categories||[]).filter(x=>x.label!=='Fuel-price research').map(category=>{const item=(category.evidence||[])[0];return `<article class="saved-plan"><strong>${escapeHTML(category.label)}</strong><p>${item?`<a href="${escapeHTML(safeProviderLink(item.url)||'#')}" target="_blank" rel="noopener noreferrer">${escapeHTML(item.title)}</a>${item.fact?` · ${escapeHTML(item.fact)}`:''}`:'No current cached reference. Refresh public research to retrieve one.'}</p></article>`;}).join('');const panel=cards?`<section class="card coverage-panel"><div class="card-heading"><h2>Vehicle, lease & financing research</h2><button class="text-link" data-tab="local">Review sources ${icon('arrow')}</button></div><p class="muted" style="font-size:11px">Public references are current only as of retrieval and are not quotes or approvals.</p>${cards}</section>`:`<section class="card coverage-panel"><div class="card-heading"><h2>Vehicle, lease & financing research</h2><button class="text-link" data-tab="local">Refresh public research ${icon('arrow')}</button></div><p class="muted" style="font-size:11px">No live reference is cached. Refreshing will perform three bounded public searches and will not alter this scenario.</p></section>`;return guardianCompareWithFuel().replace('<div class="compare-top">',panel+'<div class="compare-top">');};
document.addEventListener('click',e=>{if(e.target.closest('#refresh-market')){e.preventDefault();e.stopImmediatePropagation();modal('Refresh public research',`<p>This performs five bounded SerpApi searches: Austin fuel, Corolla Hybrid, Camry, Prius, and regional Toyota financing or lease references. It may consume five search API requests and will not change your comparison automatically.</p><button class="btn" id="confirm-market-refresh">Refresh research ${icon('search')}</button>`);}if(e.target.closest('#confirm-market-refresh')){e.preventDefault();e.stopImmediatePropagation();closeModal();loadMarket(true).then(()=>toast('Public research refreshed. Verify every source.')).catch(error=>toast(error.message));}},true);

function marketResearchPanel(){const market=marketEvidence(),categories=market?.categories||[];if(!categories.length)return `<section class="card card-pad" style="margin-top:18px"><div class="card-heading"><h2>Current market references</h2><button class="text-link" data-tab="local">Run live research ${icon('arrow')}</button></div><p class="muted">No current references are cached. A deliberate refresh runs five bounded searches for Austin fuel, three Toyota upgrade candidates, and regional Toyota finance or lease information.</p></section>`;return `<section class="card card-pad" style="margin-top:18px"><div class="card-heading"><div><h2>Current market references</h2><p class="muted">Cached ${retrievedLabel(market.retrieved_at)} · public evidence, not quotes</p></div><button class="text-link" data-tab="local">Review all sources ${icon('arrow')}</button></div><div class="market-reference-grid">${categories.map(category=>{const first=(category.evidence||[])[0];return `<article><span>${escapeHTML(category.label)}</span>${first?`<a href="${escapeHTML(safeProviderLink(first.url)||'#')}" target="_blank" rel="noopener noreferrer">${escapeHTML(first.title)}</a><p>${escapeHTML(first.fact||'Open the source to verify current terms.')}</p>`:`<strong>No result returned</strong>`}</article>`;}).join('')}</div></section>`;}

accountCompare=function(){const c=calc(),r=recommendation(),selected=serverResult.selected_upgrade||{},options=serverResult.upgrade_options||{},flow=state.freeCashFlow===''?null:Number(state.freeCashFlow),fuelSource=state.fuelEvidence?`Confirmed public reference · ${escapeHTML(state.fuelEvidence.title||'AAA')}`:'Synthetic default · run live research to replace it';const reserveStatus=(ok,remaining)=>`<div class="liquidity-check ${ok?'ok':'alert'}"><strong>${ok?'Upfront reserve protected':'Below protected cash floor'}</strong><span>${money(remaining)} remains after the one-time cost; target is ${money(state.reserve)}.</span></div>`;const monthlyStatus=(ok,value)=>`<div class="liquidity-check ${flow==null?'neutral':ok?'ok':'alert'}"><strong>${flow==null?'Monthly affordability not checked':ok?'Within monthly free cash flow':'Above monthly free cash flow'}</strong><span>${money(value)}/month ongoing${flow==null?' · add your free cash flow below':` versus ${money(flow)}/month self-reported`}.</span></div>`;return `<div class="view-header"><div><h2>Keep, finance, or lease—with the same inputs.</h2><p>Upfront liquidity and ongoing affordability are shown as separate checks.</p></div><button class="btn secondary small" data-action="assumptions">${icon('info')} Sources & assumptions</button></div><div class="evidence-banner">${icon('fuel')} Fuel input: <strong>${money(c.fuelPrice)}/gal</strong> · ${fuelSource}</div><section class="card upgrade-selector"><div><label for="upgrade-select">Upgrade vehicle</label><select id="upgrade-select">${Object.entries(options).map(([id,o])=>`<option value="${id}" ${id===state.upgradeId?'selected':''}>${escapeHTML(o.label)}</option>`).join('')}</select></div><div><label for="upgrade-mode">Acquisition path</label><select id="upgrade-mode"><option value="purchase" ${state.upgradeMode==='purchase'?'selected':''}>Finance / purchase</option><option value="lease" ${state.upgradeMode==='lease'?'selected':''}>Lease illustration</option></select></div><p>Catalog numbers are disclosed planning fixtures. Current public Toyota references appear below and are not silently treated as quotes.</p></section><div class="compare-top"><section class="card compare-card ${c.keepOK&&c.difference>=0?'recommended':''}"><span class="eyebrow">KEEP & SERVICE</span><h3>Your ${escapeHTML(vehicleName())}</h3><img src="${vehicleAsset(vehicle().model)}" alt="Your synthetic account vehicle"><div class="compare-price">${money(c.keep)} <small>/ 12 months</small></div>${reserveStatus(c.keepReserveOK,c.keepCash)}${monthlyStatus(c.keepMonthlyOK,c.keepMonthly)}<ul class="cost-list"><li><span>Profile-linked brake estimate</span><strong>${money(c.oop)}</strong></li><li><span>Routine maintenance allowance</span><strong>$600</strong></li><li><span>Fuel · 30 mpg</span><strong>${money(c.fuelKeep)}</strong></li></ul></section><section class="card compare-card ${c.replaceOK&&c.difference<0?'recommended':''}"><span class="eyebrow">${state.upgradeMode==='lease'?'LEASE ILLUSTRATION':'FINANCE / PURCHASE ILLUSTRATION'}</span><h3>${escapeHTML(selected.label||'Selected Toyota')}</h3><img src="${vehicleAsset(selected.label)}" alt="Illustration for the selected Toyota upgrade"><div class="compare-price">${money(c.replace)} <small>/ 12 months</small></div>${reserveStatus(c.replaceReserveOK,c.replaceCash)}${monthlyStatus(c.replaceMonthlyOK,c.replaceMonthly)}<ul class="cost-list"><li><span>One-time cash due</span><strong>${money(c.replacementCashDue)}</strong></li><li><span>${state.upgradeMode==='lease'?'Lease':'Loan'} payments · ${money(c.replacementPayment)} × 12</span><strong>${money(c.replacementPayment*12)}</strong></li><li><span>Routine maintenance allowance</span><strong>${money(selected.routine||300)}</strong></li><li><span>Fuel · ${Number(selected.mpg||50)} mpg</span><strong>${money(c.fuelReplace)}</strong></li><li><span>Illustrative MSRP reference</span><strong>${money(selected.msrp||0)}</strong></li></ul></section></div><section class="card controls-panel"><div class="control"><label for="miles-range">Annual driving <span class="control-value" id="miles-value">${state.miles.toLocaleString()} mi</span></label><input type="range" id="miles-range" min="6000" max="30000" step="1000" value="${state.miles}"><small>Changes fuel costs on both paths.</small></div><div class="control"><label for="repair-range">Brake estimate <span class="control-value" id="repair-value">${money(state.repair)}</span></label><input type="range" id="repair-range" min="0" max="4500" step="50" value="${state.repair}"><small>Starts from the profile-linked synthetic estimate; editable by the user.</small></div><div class="control"><label for="reserve-range">Protected cash floor <span class="control-value" id="reserve-value">${money(state.reserve)}</span></label><input type="range" id="reserve-range" min="500" max="6000" step="100" value="${state.reserve}"><small>Minimum cash remaining after the one-time repair or cash due.</small></div></section><section class="card card-pad" style="margin-top:16px"><label for="free-cash-flow"><strong>Optional monthly free cash flow</strong><br><small>Income remaining each month after housing, debt, food, and other commitments.</small></label><div class="inline-planning-input"><span>$</span><input id="free-cash-flow" type="number" min="0" max="50000" step="50" value="${flow==null?'':flow}" placeholder="e.g. 900"><button class="btn secondary small" id="save-free-cash-flow">Update monthly check</button></div><p class="muted">This does not increase cash on hand. It only evaluates ongoing monthly affordability.</p></section><div id="comparison-result" class="result-banner ${r.warning?'warning':''}"><span class="check-circle">${r.warning?'!':'✓'}</span><div><h3>${escapeHTML(r.title)}</h3><p>${escapeHTML(r.text)}</p></div></div>${marketResearchPanel()}<div class="comparison-actions"><button class="btn" data-tab="plan">Build my next move ${icon('arrow')}</button><button class="btn secondary" data-tab="local">Review service and market research</button></div>`;};

async function loadNextMoveSummary(){const key=JSON.stringify({scenario:scenario(),context:userReportedContext(),market:marketEvidence()?.retrieved_at||null});if(nextMoveLoading||nextMoveKey===key)return;nextMoveLoading=true;nextMoveKey=key;nextMoveSummary=null;if(currentTab==='plan')renderView();try{nextMoveSummary=await api('/chat',{profile:state.profile,scenario:scenario(),view:'plan',message:'Summarize my best next move using the complete comparison, profile, vehicle status, service history, self-reported maintenance updates, monthly affordability input, cached provider evidence, and cached market research. Clearly separate verified profile facts, user-reported inputs, public references, and synthetic assumptions. Do not propose a scenario change.',history:[],user_context:userReportedContext()});}catch(error){nextMoveSummary={message:`Gemini summary unavailable: ${error.message}`,fallback:true,warning:error.message};}finally{nextMoveLoading=false;if(currentTab==='plan')renderView();}}
const guardianPlanLegacy=plan;
plan=function(){const base=guardianPlanLegacy();const source=nextMoveSummary?(nextMoveSummary.fallback?'Deterministic fallback':`Gemini · ${integrationStatus?.gemini?.model||'validated response'}`):nextMoveLoading?'Gemini is combining your current context…':'Summary not generated yet';const summary=`<section class="card card-pad next-move-summary"><div class="card-heading"><div><div class="eyebrow">CONTEXT-AWARE NEXT MOVE</div><h2>Your complete planning summary</h2></div><span class="badge ${nextMoveSummary&&!nextMoveSummary.fallback?'green':''}">${escapeHTML(source)}</span></div><p>${escapeHTML(nextMoveSummary?.message||'Open this tab to combine your current profile, service updates, affordability inputs, provider evidence, market research, and selected upgrade path.')}</p>${nextMoveSummary?.warning?`<div class="evidence-banner">${icon('info')} ${escapeHTML(nextMoveSummary.warning)}</div>`:''}<button class="btn secondary small" id="refresh-next-move" ${nextMoveLoading?'disabled':''}>${icon('spark')} Regenerate from current context</button></section>`;return base.replace('<div class="plan-grid">',summary+'<div class="plan-grid">');};
document.addEventListener('click',e=>{if(!e.target.closest('#refresh-next-move'))return;nextMoveKey=null;loadNextMoveSummary();});
// Scoped maintenance form layout: avoids affecting the established Guardian cards and modals.
if(document.head)document.head.insertAdjacentHTML('beforeend','<style>#maintenance-update-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 16px;margin-top:20px}#maintenance-update-form label{display:flex;flex-direction:column;gap:6px;color:#4d545a;font-size:11px;font-weight:700}#maintenance-update-form input,#maintenance-update-form select,#maintenance-update-form textarea{width:100%;min-height:39px;border:1px solid #d7dade;border-radius:5px;padding:8px 10px;background:#fff;color:#202428;font-size:12px}#maintenance-update-form textarea{min-height:88px;resize:vertical}#maintenance-update-form label:has(textarea),#maintenance-update-form .btn{grid-column:1/-1}#maintenance-update-form .btn{justify-self:start;margin:2px 0 0}.vehicle-snapshot{margin-top:18px}.vehicle-snapshot-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.vehicle-snapshot-grid article{border:1px solid #e4e6e8;border-radius:8px;padding:14px;background:#fff}.vehicle-snapshot-grid span{display:block;color:#737b80;font-size:10px;margin-bottom:7px}.vehicle-snapshot-grid strong{font-size:17px}.tire-readings{font-size:12px!important;line-height:1.55}.snapshot-note{font-size:10px;color:#737b80;margin:10px 0 0}@media(max-width:640px){#maintenance-update-form{grid-template-columns:1fr;gap:12px}#maintenance-update-form label:has(textarea),#maintenance-update-form .btn{grid-column:auto}.vehicle-snapshot-grid{grid-template-columns:1fr}}</style>');

const guardianOverviewLegacy=overview;
overview=function(){const html=guardianOverviewLegacy(),telemetry=profile()?.telemetry||{},tires=telemetry.tire_pressure_psi||{},battery=telemetry.battery||{};const tireValues=Object.values(tires).filter(Number.isFinite);const tireStatus=tireValues.length&&Math.min(...tireValues)<32?'Check pressure':'Pressure balanced';const batteryPrimary=battery.state_of_charge_percent!=null?`${battery.state_of_charge_percent}% charge`:`${battery.health_percent??'—'}% health`;const batteryDetail=battery.state_of_charge_percent!=null?`${Number(battery.estimated_range_miles||0).toLocaleString()} mi estimated range · ${Number(battery.equivalent_full_cycles||0).toLocaleString()} equivalent cycles`:`${battery.voltage??'—'} V · ${battery.type||'12V'} battery`;const snapshot=`<section class="card card-pad vehicle-snapshot"><div class="card-heading"><div><div class="eyebrow">SIMULATED VEHICLE SNAPSHOT</div><h2>Connected vehicle status</h2></div>${icon('trend')}</div><div class="vehicle-snapshot-grid"><article><span>Odometer</span><strong>${Number(telemetry.odometer_miles??vehicle().mileage??0).toLocaleString()} mi</strong></article><article><span>Tire pressure · ${escapeHTML(tireStatus)}</span><strong class="tire-readings">FL ${tires.front_left??'—'} · FR ${tires.front_right??'—'}<br>RL ${tires.rear_left??'—'} · RR ${tires.rear_right??'—'} psi</strong></article><article><span>${escapeHTML(battery.type||'Vehicle')} battery</span><strong>${escapeHTML(batteryPrimary)}</strong><p>${escapeHTML(batteryDetail)}</p></article></div><p class="snapshot-note">Synthetic Toyota-app-style snapshot captured ${telemetry.captured_at?retrievedLabel(telemetry.captured_at):'for this demo'}. It is not a live telematics feed.</p></section>`;return html+snapshot;};

if(document.head)document.head.insertAdjacentHTML('beforeend','<style>.upgrade-selector{display:grid;grid-template-columns:minmax(220px,1fr) minmax(190px,.65fr);gap:16px;padding:18px;margin-bottom:18px;align-items:end}.upgrade-selector label{display:block;font-size:10px;font-weight:800;color:#626a70;margin-bottom:7px}.upgrade-selector select{width:100%;border:1px solid #d9dcdf;border-radius:6px;padding:10px;background:#fff}.upgrade-selector>p{grid-column:1/-1;margin:0;font-size:10px;color:#737b80}.liquidity-check{border-radius:7px;padding:10px 12px;margin:10px 0;display:flex;flex-direction:column;gap:3px}.liquidity-check strong{font-size:11px}.liquidity-check span{font-size:9px}.liquidity-check.ok{background:#eef8f1;color:#267a4b}.liquidity-check.alert{background:#fff0f0;color:#b92d33}.liquidity-check.neutral{background:#f3f5f6;color:#626a70}.inline-planning-input{display:flex;gap:10px;align-items:center;margin-top:10px}.inline-planning-input input{max-width:190px;border:1px solid #d9dcdf;border-radius:5px;padding:9px}.market-reference-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-top:14px}.market-reference-grid article{border:1px solid #e4e6e8;border-radius:7px;padding:12px;min-width:0}.market-reference-grid span{display:block;font-size:9px;font-weight:800;color:#737b80;margin-bottom:6px}.market-reference-grid a{display:block;font-weight:700;font-size:11px;color:#222}.market-reference-grid p{font-size:9px;margin-top:6px;color:#737b80}.comparison-actions{display:flex;gap:12px;margin-top:20px;flex-wrap:wrap}@media(max-width:760px){.upgrade-selector,.market-reference-grid{grid-template-columns:1fr}.upgrade-selector>p{grid-column:auto}.inline-planning-input{align-items:stretch;flex-wrap:wrap}}</style>');

boot();
